    p = ''.join(r.choice(PTOK) for _ in range(r.randint(1, 6)))
    if r.random() < 0.3: p = '!' + p
    if r.random() < 0.15: p = ' ' + p
    if r.random() < 0.2: p += '/'
    return p
def rand_tree(r):
    files = {}; modes = {}
    dirs = ['']
    for _ in range(r.randint(1, 4)):
        parent = r.choice(dirs)
        dirs.append(parent + r.choice(NAMES) + '/')
    for _ in range(r.randint(1, 12)):
        p = r.choice(dirs) + r.choice(NAMES)
        c = '@generated\n' if r.random() < 0.08 else ''
