"""Decide which files in a project tree are excluded by its .packignore files.

This is a pure-Python reimplementation of `packignore`, the legacy exclusion
engine. docs/PACKIGNORE.md describes the basics; the rules below are what the
engine actually does, including the parts the docs leave out.

The tree
--------
The engine sees the regular files under the root (symlinks and special files
are skipped, as is a `.git` directory directly under the root), visited in
`os.walk` order. It stores them on a case-insensitive, normalization-insensitive
filesystem: two paths whose components are canonically caseless-equal
(NFD + full case folding) are the same entry. The first path seen supplies the
name; the last one supplies the content and mode. A file colliding with a
directory is an error, and so is a file name that is not valid UTF-8.

.packignore syntax
------------------
- The file is UTF-8 (strict, no BOM handling) and split with str.splitlines().
  Each line is str.strip()ped. Empty lines and lines starting with `;` are
  skipped. `#` is NOT a comment.
- A leading `!` negates (re-includes); the rest of the line is the pattern,
  taken as is.
- Trailing `/`s mean "directories only" and are removed. Leading `/`s are
  removed. If the pattern contains a `/` (including a removed leading one) it
  is anchored: matched against the whole path relative to the directory
  holding the .packignore. Otherwise it matches a file or directory name at
  any depth below that directory.
- `*` matches any run of characters except `/`, `?` exactly one. A path
  segment that is exactly `**` matches zero or more segments. Everything else,
  including `[`, `]` and `\\`, is literal. Matching is case-sensitive.

Precedence
----------
A file is decided by the deepest path (the file itself, else its nearest
ancestor directory) that any pattern matches. Among the patterns matching that
path, the winner is the one from the deepest .packignore, then the one with
the most literal characters (everything except `*`, `?` and `/`), then the
last one in the file. A negated winner keeps the path, any other winner
excludes it.

If no pattern matches the file itself, it is still excluded when it is
executable (any x bit) or its first line (up to the first b"\\n") contains
`@generated`.

A .packignore is read only if the directory holding it is not excluded (the
root's always is). Being excluded itself does not stop it from being read.
A .packignore that would be read but is a directory, or is not valid UTF-8,
is an error.
"""

import os
import re
import stat
import unicodedata

_PACKIGNORE = ".packignore"


def _fold(name):
    """Key under which the engine's filesystem considers names equal."""
    return unicodedata.normalize("NFD", unicodedata.normalize("NFD", name).casefold())


class _Dir:
    def __init__(self, name):
        self.name = name
        self.children = {}  # folded name -> _Dir or _File


class _File:
    def __init__(self, name, source):
        self.name = name
        self.source = source  # path of the last file stored under this name


def _walk(root):
    """Yield (relative path, absolute path) for the files the engine sees."""
    for dirpath, dirnames, filenames in os.walk(root):
        if os.path.samefile(dirpath, root) and ".git" in dirnames:
            dirnames.remove(".git")
        for name in filenames:
            full = os.path.join(dirpath, name)
            if os.path.islink(full) or not os.path.isfile(full):
                continue
            rel = os.path.relpath(full, root).replace(os.sep, "/").lstrip("/")
            try:
                rel.encode("utf-8")
            except UnicodeEncodeError:
                raise ValueError(f"packignore: {rel!r}: file name is not valid UTF-8") from None
            yield rel, full


def _build_tree(root):
    top = _Dir("")
    for rel, full in _walk(root):
        parts = rel.split("/")
        node = top
        for part in parts[:-1]:
            child = node.children.get(_fold(part))
            if child is None:
                child = node.children[_fold(part)] = _Dir(part)
            elif not isinstance(child, _Dir):
                raise ValueError(f"packignore: {rel}: path collides with a file")
            node = child
        key = _fold(parts[-1])
        child = node.children.get(key)
        if child is None:
            node.children[key] = _File(parts[-1], full)
        elif isinstance(child, _File):
            child.source = full
        else:
            raise ValueError(f"packignore: {rel}: path collides with a directory")
    return top


def _is_generated(path):
    """True if the first line of the file contains b"@generated"."""
    needle = b"@generated"
    tail = b""
    with open(path, "rb") as f:
        while True:
            chunk = f.read(65536)
            if not chunk:
                return False
            nl = chunk.find(b"\n")
            if nl >= 0:
                chunk = chunk[:nl]
            if needle in tail + chunk:
                return True
            if nl >= 0:
                return False
            tail = (tail + chunk)[-(len(needle) - 1):]


def _is_executable(path):
    return bool(os.stat(path).st_mode & (stat.S_IXUSR | stat.S_IXGRP | stat.S_IXOTH))


def _segment_regex(seg):
    out = []
    for ch in seg:
        if ch == "*":
            out.append("[^/]*")
        elif ch == "?":
            out.append("[^/]")
        else:
            out.append(re.escape(ch))
    return re.compile("".join(out), re.DOTALL)


class _Rule:
    def __init__(self, line, depth, index):
        self.negated = line.startswith("!")
        if self.negated:
            line = line[1:]
        self.dir_only = line.endswith("/")
        line = line.rstrip("/")
        self.anchored = "/" in line
        line = line.lstrip("/")
        # (deeper .packignore, more literal characters, later line) wins
        self.rank = (depth, sum(1 for ch in line if ch not in "*?/"), index)
        if not line:
            self.segments = None  # matches nothing
        elif self.anchored:
            self.segments = [None if seg == "**" else _segment_regex(seg) for seg in line.split("/")]
        else:
            self.segments = [_segment_regex(line)]

    def matches(self, rel, is_dir):
        """`rel` is the path's segments relative to the .packignore's directory."""
        if self.segments is None or (self.dir_only and not is_dir):
            return False
        if not self.anchored:
            return self.segments[0].fullmatch(rel[-1]) is not None
        return _match_segments(self.segments, rel)


def _match_segments(pattern, path):
    # pattern: compiled segments, None for `**`
    states = {0}
    for seg in path:
        nxt = set()
        for i in _close(pattern, states):
            if i < len(pattern):
                if pattern[i] is None:
                    nxt.add(i)
                elif pattern[i].fullmatch(seg):
                    nxt.add(i + 1)
        states = nxt
        if not states:
            return False
    return len(pattern) in _close(pattern, states)


def _close(pattern, states):
    """Add the states reachable by letting `**` match zero segments."""
    out = set(states)
    stack = list(states)
    while stack:
        i = stack.pop()
        if i < len(pattern) and pattern[i] is None and i + 1 not in out:
            out.add(i + 1)
            stack.append(i + 1)
    return out


def _read_rules(path, depth):
    with open(path, "rb") as f:
        text = f.read().decode("utf-8")
    rules = []
    for line in text.splitlines():
        line = line.strip()
        if not line or line.startswith(";"):
            continue
        rules.append(_Rule(line, depth, len(rules)))
    return rules


def _decide(sources, path, is_dir):
    """Return True/False if a pattern decides `path`, None if none matches.

    `sources` is a list of (directory segments, rules) for every .packignore
    that applies to `path`.
    """
    best = None
    for base, rules in sources:
        rel = path[len(base):]
        for rule in rules:
            if (best is None or rule.rank > best.rank) and rule.matches(rel, is_dir):
                best = rule
    return None if best is None else not best.negated


def ignored_files(root):
    """Return the files under `root` that its .packignore files exclude.

    Paths are relative to `root`, use "/" as the separator, and are sorted.
    Only files are listed, never directories. A `.git` directory directly
    under `root` is skipped.
    """
    out = []

    def visit(node, path, excluded, sources):
        pi = node.children.get(_fold(_PACKIGNORE))
        if not excluded and pi is not None and pi.name == _PACKIGNORE:
            if isinstance(pi, _Dir):
                raise ValueError(f"packignore: {'/'.join(path + [_PACKIGNORE])} is a directory")
            sources = sources + [(path, _read_rules(pi.source, len(path)))]
        for child in node.children.values():
            child_path = path + [child.name]
            if isinstance(child, _Dir):
                decided = _decide(sources, child_path, True)
                visit(child, child_path, excluded if decided is None else decided, sources)
            else:
                decided = _decide(sources, child_path, False)
                if decided is None:
                    decided = excluded or _is_executable(child.source) or _is_generated(child.source)
                if decided:
                    out.append("/".join(child_path))

    visit(_build_tree(root), [], False, [])
    return sorted(out)

