import random, sys
sys.path.insert(0, '/work/repo')
import fuzz, fuzz3
def rand_tree(r):
    files = {}; modes = {}
    dirs = ['']
    for _ in range(r.randint(3, 14)):
        base = max(dirs, key=len) if r.random() < 0.5 else r.choice(dirs)
        dirs.append(base + r.choice(fuzz3.NAMES) + '/')
    for _ in range(r.randint(1, 25)):
        p = r.choice(dirs) + r.choice(fuzz3.NAMES)
        files[p] = '@generated' if r.random() < 0.1 else ''
        if r.random() < 0.1: modes[p] = 0o755
    for p in list(files):
        if any(q.startswith(p + '/') for q in files): del files[p]
    paths = list(files) + [d.rstrip('/') for d in dirs if d]
    for d in dirs:
        if r.random() < (0.95 if d == '' else 0.4):
            sub = [p[len(d):] for p in paths if p.startswith(d) and p != d.rstrip('/')] or ['a']
            pats = []
            for _ in range(r.randint(1, 10)):
                p = fuzz3.pattern_from(r, sub)
                if r.random() < 0.3:
                    segs = p.lstrip('!').split('/')
                    segs.insert(r.randint(0, len(segs)), '**')
                    p = ('!' if p.startswith('!') else '') + '/'.join(segs)
                pats.append(p)
            files[d + '.packignore'] = '\n'.join(pats) + '\n'
    for p in list(files):
        if any(q.startswith(p + '/') for q in files): del files[p]
    return files, modes
fuzz.rand_tree = rand_tree
if __name__ == '__main__':
    start, n = int(sys.argv[1]), int(sys.argv[2])
    bad = 0
    for s in range(start, start + n):
        res = fuzz.one(s)
        if res:
            bad += 1
            if bad <= 3: print(ascii(res)[:1500])
    print('mismatches', bad, 'of', n)
